		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	ExpReturn, ExpReturn, ExpReturn, ExpReturn
		dc.l	ExpReturn, $00000000, VBlankInt, ExpReturn
		dc.l	$00000000, $00000000, $00000000, $00000000
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF
		dc.l	$FFFFFFFF, $FFFFFFFF, $FFFFFFFF, $FFFFFFFF

ConsoleName:	dc.b	"SEGA GENESIS    "
ProductDate:	dc.b	"(C)T-50 1993.JUL"
TitleLocal:	dc.b	"NHL Hockey '94                                  "
TitleInter:	dc.b	"NHL Hockey '94                                  "
SerialNumber:	dc.b	"GM T-50656 -"
Checksum:	dc.l	$30305512			; This checksum is technically unused (but also uncounted)
IOSupport:	dc.b	"J               "
ROMStart:	dc.l	StartROM
ROMFinish:	dc.l	FinishROM-1
RAMStart:	dc.l	$00FF0000
RAMFinish:	dc.l	$00FFFFFF
		;	;;;;;%1E1TT000,%00100000	; E = Erase SRAM on start (0 Yes | 1 No) 
SupportRAM:	dc.b	'RA',%11111000,%00100000	; TT = Type (00 Even & Odd | 10 Even | 11 Odd)
SRAMStart:	dc.l	$200001
SRAMFinish:	dc.l	$203FFF
ModemInfo:	dc.b	"                                                    "
ProductRegion:	dc.b	"UE              "

; ===========================================================================
; ---------------------------------------------------------------------------
; Starting routine (setting up the Mega Drive's individual components)
; ---------------------------------------------------------------------------

SetupGame:
		tst.l	($A10008).l				; have controller ports 1 (A) or 2 (B) been initialised?
		bne.s	SG_Reset				; if so, branch
		tst.w	($A1000C).l				; check controller port 3 (ext)

SG_Reset:
		bne.s	SG_SkipSetup				; if any port has been initialise, branch (reset button was pressed).
		lea	SG_Values(pc),a5			; load address of setup values
		movem.w	(a5)+,d5-d7				; load VDP value, 68k RAM size and Z80 port values to d5, d6 and d7 respectively
		movem.l	(a5)+,a0-a4				; load Z80 and VDP access addresses to a0, a1, a2, a3 and a4
		move.b	-$10FF(a1),d0				; load Mega Drive hardware version (offset A10001)
		andi.b	#$0F,d0					; get only the version nybble
		beq.s	SG_NoTMSS				; if it is 0, branch (version 0 does not have TMSS security)
		move.l	#'SEGA',$2F00(a1)			; copy "SEGA" security code to TMSS chip (offset A14000)

SG_NoTMSS:
		move.w	(a4),d0					; release latch
		moveq	#$00,d0					; clear d0
		movea.l	d0,a6					; clear a6
		move.l	a6,usp					; clear user stack pointer (unused)
		moveq	#(SG_RegVDP_End-SG_RegVDP)-1,d1		; set repeat times

SG_SetupVDP:
		move.b	(a5)+,d5				; load value next to register ID
		move.w	d5,(a4)					; save to VDP (setting the register)
		add.w	d7,d5					; increase register ID
		dbf	d1,SG_SetupVDP				; repeat for all VDP registers
		move.l	(a5)+,(a4)				; write DMA destination to VDP (VRAM 0000)
		move.w	d0,(a3)					; set DMA fill value to 00 (DMA starts here, clears entire VRAM)
		move.w	d7,(a1)					; set Z80 stop on
		move.w	d7,(a2)					; set Z80 reset off

SG_WaitZ80:
		btst.b	d0,(a1)					; has the Z80 stopped yet?
		bne.s	SG_WaitZ80				; if not, branch and loop until it has
		moveq	#(SG_Z80_End-SG_Z80)-1,d2		; set repeat times

SG_LoadZ80:
		move.b	(a5)+,(a0)+				; copy Z80 instructions to Z80 RAM
		dbf	d2,SG_LoadZ80				; repeat until all bytes are copied over
		move.w	d0,(a2)					; set Z80 reset on
		move.w	d0,(a1)					; set Z80 stop off
		move.w	d7,(a2)					; set Z80 reset off

SG_ClearRAM:
		move.l	d0,-(a6)				; clear long-word of 68k RAM and move back
		dbf	d6,SG_ClearRAM				; repeat until all 68k RAM from 0000 to FFFF is clear
		move.l	(a5)+,(a4)				; turn VDP DMA off and set VDP auto increment to 2
		move.l	(a5)+,(a4)				; set VDP to CRAM write mode (address 0000)
		moveq	#$20-1,d3				; set repeat times

SG_ClearCRAM:
		move.l	d0,(a3)					; clear colours
		dbf	d3,SG_ClearCRAM				; repeat until the entire palette is clear (black)
		move.l	(a5)+,(a4)				; set VDP to VSRAM write mode (address 0000)
		moveq	#$14-1,d4				; set repeat times

SG_ClearVSRAM:
		move.l	d0,(a3)					; clear vertical scroll positions
		dbf	d4,SG_ClearVSRAM			; repeat until all scroll positions are set to 0000
		moveq	#(SG_PSG_End-SG_PSG)-1,d5		; set repeat times

SG_SetupPSG:
		move.b	(a5)+,$11(a3)				; write PSG volume values to PSG port (offset C00011)
		dbf	d5,SG_SetupPSG				; repeat for all PSG channels
		move.w	d0,(a2)					; set Z80 reset on
		movem.l	(a6),d0-a6				; clear all 68k registers
		move	#$2700,sr				; disable all interrupts

SG_SkipSetup:
		bra.s	StartGame				; continue to actual game code

; ---------------------------------------------------------------------------
; Setup values
; ---------------------------------------------------------------------------

SG_Values:	dc.w	$8000					; VDP register value (80??)
		dc.w	$FFFF/4					; size of 68k RAM
		dc.w	$0100					; Z80 bus/reset value
		dc.l	$A00000					; address of Z80 RAM
		dc.l	$A11100					; Z80 bus request port
		dc.l	$A11200					; Z80 reset port
		dc.l	$C00000					; VDP data port
		dc.l	$C00004					; VDP control port

	; --- VDP register values ---

SG_RegVDP:	dc.b	%00000100				; 00LH 01CD - Leftover SMS bar (0N|1Y) | H-Interrupt (0N|1Y) | H,V Counter (0N|1Y) | Disable video signal (0N|1Y)
		dc.b	%00010100				; SDVM P100 - SMS mode (0N|1Y) | Display (0N|1Y) | V-Interrupt (0N|1Y) | DMA (0N|1Y) | V-resolution (0-1C|1-1E)
		dc.b	(($C000)>>$0A)&$FF			; 00FE DCBA - Scroll Plane A Map Table VRam address
		dc.b	(($F000)>>$0A)&$FF			; 00FE DCB0 / 00FE DC00 (20 H-resol) - Window Plane A Map Table VRam address
		dc.b	(($E000)>>$0D)&$FF			; 0000 0FED - Scroll Plane B Map Table VRam address
		dc.b	(($D800)>>$09)&$FF			; 0FED CBA9 / 0FED CBA0 (20 H-resol) - Sprite Plane Map Table VRam address
		dc.b	%00000000				; 0000 0000 - Unknown/Unused Register
		dc.b	$00					; 00PP CCCC - Backdrop Colour: Palette Line | Colour ID
		dc.b	%00000000				; 0000 0000 - Unknown/Unused Register
		dc.b	%00000000				; 0000 0000 - Unknown/Unused Register
		dc.b	$FF					; 7654 3210 - H-Interrupt Register
		dc.b	%00000000				; 0000 EVHH - External Interrupt (0N|1Y) | V-Scroll (0-Full|1-2Celled) | H-Scroll: (00-Full|10-Celled|11-Sliced)
		dc.b	%10000001				; APHE SNNB - H-resol (0N|1Y) | Pixel int (0N|1Y) | H-sync (0N|1Y) | Extern-pix (0N|1Y) | S/H (0N|1Y) | Interlace (00N|01Y|11-Split) | H-resol (0-20|1-28)
		dc.b	(($DC00)>>$0A)&$FF			; 00FE DCBA - Horizontal Scroll Table VRam address
		dc.b	%00000000				; 0000 0000 - Unknown/Unused Register
		dc.b	$01					; 7654 3210 - Auto Increament
		dc.b	%00000001				; 00VV 00HH - Plane Y Size (00-20|01-40|11-80) | Plane X size (00-20|01-40|11-80)
		dc.b	$00					; 7654 3210 - Window Horizontal Position
		dc.b	$00					; 7654 3210 - Window Vertical Position
		dc.b	$FF					; DMA fill Size (Lower Byte --FF)
		dc.b	$FF					; DMA fill Size (Upper Byte FF--)
		dc.b	$00					; DMA fill Source (Low Byte ----00)
		dc.b	$00					; DMA fill Source (Mid Byte --00--)
		dc.b	$80					; DMA fill Source (High Byte 80----)
SG_RegVDP_End:	dc.l	$40000080				; DMA fill destination (VRAM 0000)

	; --- Z80 instructions ---

SG_Z80:		dc.b	$AF,$01,$D9,$1F,$11,$27,$00,$21		; ...these are just instructions for the Z80
		dc.b	$26,$00,$F9,$77,$ED,$B0,$DD,$E1		; to clear its own RAM, its registers, and to
		dc.b	$FD,$E1,$ED,$47,$ED,$4F,$D1,$E1		; trap itself in an endless loop.
		dc.b	$F1,$08,$D9,$C1,$D1,$E1,$F1,$F9
		dc.b	$F3,$ED,$56,$36,$E9,$E9
SG_Z80_End:	even

	; --- VDP final settings ---

		dc.w	$8104					; Display Off; V-Interrupt Off; DMA Off; V 28 Cell PAL/NTSC Mode
		dc.w	$8F02					; Auto Increament: By 2
		dc.l	$C0000000				; CRAM Write 0000
		dc.l	$40000010				; VSRAM Write 0000

	; --- PSG volume settings ---
	; PSG Volume control format: "PZZF VVVV"
	;	P = Part (1 writing first byte | 0 writing second byte)
	;	ZZ = Channel
	;		00 = PSG 1 tone
	;		01 = PSG 2 tone
	;		10 = PSG 3 tone
	;		11 = PSG 4 noise
	;	F = Function (1 writing volume | 0 writing frequency)
	;	VVVV = Volume (0 = loud | F = quiet)
	; ---------------------------

SG_PSG:		dc.b	%10010000|$0F				; PSG 1 volume (Mute)
		dc.b	%10110000|$0F				; PSG 2 volume (Mute)
		dc.b	%11010000|$0F				; PSG 3 volume (Mute)
		dc.b	%11110000|$0F				; PSG 4 volume (Mute)
SG_PSG_End:	even

; ===========================================================================
; ---------------------------------------------------------------------------
; The start of the actual game's setup
; ---------------------------------------------------------------------------

StartGame:
		tst.w	($C00004).l				; release latch
		jsr	CalcChecksum
		bra.w	RunGame

